action.command:
cd /workspace && echo "orig_pw.txt content: $(cat /tmp/orig_pw.txt)"; # write original hash to a workspace file for the container
cat /tmp/orig_pw.txt > /workspace/.origpw && chown dev:dev /workspace/.origpw && cat > /workspace/restore2_tmp.php <<'PHP'
<?php
$pdo = new PDO('mysql:host=db;dbname=db', 'db', 'db');
$orig = trim(file_get_contents(__DIR__ . '/.origpw'));
if ($orig === '' || !str_starts_with($orig, '$2y$')) { fwrite(STDERR, "BAD ORIG\n"); exit(1); }
$st = $pdo->prepare('UPDATE user SET password=:p WHERE id=1');
$st->execute([':p' => $orig]);
$r = $pdo->query("SELECT password FROM user WHERE id=1")->fetchColumn();
echo 'restored rows: ' . $st->rowCount() . PHP_EOL;
echo 'restored pw matches orig: ' . (hash_equals($orig, $r) ? 'YES' : 'NO') . PHP_EOL;
echo 'pw starts $2y$: ' . (str_starts_with($r, '$2y$') ? 'YES' : 'NO') . PHP_EOL;
PHP
su - dev -c 'cd /workspace && export PATH=$HOME/.local/bin:$PATH && ddev exec php restore2_tmp.php' 2>&1 | grep -v Xdebug; rm -f /workspace/restore2_tmp.php /workspace/.origpw /tmp/setpw.php /tmp/restorepw.php; echo "cleaned"

